<?php
declare(strict_types=1);
function workflow_routes(App $a,string $path,array $b,string $method): ?array {
 if($path==='/attendance-requests'&&$method==='GET')return [200,['rows'=>$a->all('SELECT r.*,u.name,u.role,(SELECT name FROM {{users}} WHERE id=r.reviewed_by) reviewer_name FROM {{attendance_requests}} r JOIN {{users}} u ON u.id=r.user_id'.($a->user['role']==='employee'?' WHERE r.user_id=?':'').' ORDER BY r.created_at DESC LIMIT 500',$a->user['role']==='employee'?[$a->user['id']]:[])]];
 if($path==='/attendance-requests'&&$method==='POST'){validate_correction($b);$a->assertOpen($b['time']);if($a->one("SELECT id FROM {{attendance_requests}} WHERE user_id=? AND shift=? AND type=? AND time=? AND status='pending'",[$a->user['id'],$b['shift'],$b['type'],$b['time']]))fail('Yêu cầu đã được gửi, hãy chờ quản lý xử lý.',409);if($b['shift']==='ot'&&$b['type']==='in'&&($b['ot_confirmed']??false)!==true)fail('Xác nhận bạn thực sự làm OT trước khi gửi.');$a->run('INSERT INTO {{attendance_requests}}(user_id,shift,type,time,reason,created_at) VALUES(?,?,?,?,?,?)',[$a->user['id'],$b['shift'],$b['type'],$b['time'],trim($b['reason']),now_ms()]);return [201,['id'=>(int)$a->db->lastInsertId()]];}
 if(preg_match('~^/attendance-requests/(\d+)/review$~D',$path,$m)&&$method==='POST'){$a->requireManager();$r=$a->one('SELECT * FROM {{attendance_requests}} WHERE id=?',[(int)$m[1]]);if(!$r)fail('Không tìm thấy yêu cầu.',404);if($r['status']!=='pending')fail('Yêu cầu đã được xử lý.',409);if($r['user_id']===$a->user['id'])fail('Không được tự xử lý yêu cầu của mình.',403);$target=$a->target($r['user_id']);if(!in_array($b['status']??'', ['approved','rejected'],true)||!is_string($b['note']??null)||strlen(trim($b['note']))<5||strlen($b['note'])>1500)fail('Chọn kết quả và ghi chú xử lý từ 5–500 ký tự.');$event=null;if($b['status']==='approved'){$a->assertOpen($r['time']);$all=$a->events($target['id']);if($r['shift']!=='ot')foreach($all as $e)if($e['shift']===$r['shift']&&$e['work_date']===local_day($r['time'])&&$e['type']===$r['type'])fail('Đã có lượt chấm loại này trong ca, không ghi trùng.',409);$prefix=array_values(array_filter($all,fn($e)=>$e['time']<$r['time']));$d=attendance_decision($prefix,$r['shift'],$r['time'],true);if($d['type']!==$r['type'])fail('Sai thứ tự vào/ra. Hãy bổ sung lượt còn thiếu trước.',409);$prefix[]=['type'=>$r['type'],'shift'=>$r['shift'],'time'=>$r['time'],'work_date'=>$d['workDate']];foreach($all as $e)if($e['time']>=$r['time']&&($r['shift']==='ot'||$e['shift']===$r['shift']&&$e['work_date']===local_day($r['time']))){$next=attendance_decision($prefix,$e['shift'],$e['time'],true);if($next['type']!==$e['type'])fail('Bổ sung này xung đột với lịch sử phía sau.',409);$prefix[]=$e;}$a->run("INSERT INTO {{events}}(user_id,type,time,shift,work_date,source,recorded_by,recorded_at,reason,ot_confirmed_at) VALUES(?,?,?,?,?,'manual',?,?,?,?)",[$r['user_id'],$r['type'],$r['time'],$r['shift'],$d['workDate'],$a->user['id'],now_ms(),'Bổ sung theo yêu cầu #'.$r['id'].': '.$r['reason'].' | '.$b['note'],$r['shift']==='ot'&&$r['type']==='in'?now_ms():null]);$event=(int)$a->db->lastInsertId();}$a->run('UPDATE {{attendance_requests}} SET status=?,reviewed_by=?,reviewed_at=?,review_note=?,event_id=? WHERE id=?',[$b['status'],$a->user['id'],now_ms(),trim($b['note']),$event,$r['id']]);$a->audit($r['user_id'],$b['status'].'_request');return [200,['ok'=>true]];}
 if($path==='/payroll/closures'&&$method==='GET'){$a->requireManager();$month=valid_month($_GET['month']??'');return [200,['rows'=>$a->all('SELECT c.id,c.month,c.closed_at,c.reopened_at,c.reopen_reason,(SELECT name FROM {{users}} WHERE id=c.closed_by) closed_by_name,(SELECT name FROM {{users}} WHERE id=c.reopened_by) reopened_by_name FROM {{payroll_closures}} c WHERE month=? ORDER BY id DESC',[$month])]];}
 if($path==='/payroll/close'&&$method==='POST'){$a->requireManager();$month=valid_month($b['month']??'');if($month>=substr(local_day(now_ms()),0,7))fail('Chỉ chốt tháng đã kết thúc.');if($a->closure($month))fail('Tháng đã được chốt.',409);$rows=$a->summaries($month);if(function_exists('payroll_apply'))$rows=payroll_apply($a,$month,$rows);foreach($rows as $p)if($p['incomplete']||$p['otIncomplete'])fail('Còn ca hoặc OT thiếu chấm ra. Xử lý đầy đủ trước khi chốt.',409);foreach($a->all("SELECT time FROM {{attendance_requests}} WHERE status='pending'") as $r)if(substr(local_day($r['time']),0,7)===$month)fail('Còn yêu cầu bổ sung chưa được xử lý.',409);$commissions=array_values(array_filter($a->all('SELECT * FROM {{commissions}}'),fn($c)=>substr(local_day($c['served_at']),0,7)===$month));$a->run('INSERT INTO {{payroll_closures}}(month,rows_json,commissions_json,closed_by,closed_at) VALUES(?,?,?,?,?)',[$month,json_encode($rows,JSON_THROW_ON_ERROR),json_encode($commissions,JSON_THROW_ON_ERROR),$a->user['id'],now_ms()]);$a->audit($a->user['id'],'close_payroll:'.$month);return [201,['ok'=>true]];}
 if($path==='/payroll/reopen'&&$method==='POST'){$a->requireAdmin();$month=valid_month($b['month']??'');if(!is_string($b['reason']??null)||strlen(trim($b['reason']))<10||strlen($b['reason'])>1500)fail('Ghi lý do mở lại từ 10–500 ký tự.');$c=$a->closure($month);if(!$c)fail('Tháng chưa được chốt.',409);$a->run('UPDATE {{payroll_closures}} SET reopened_by=?,reopened_at=?,reopen_reason=? WHERE id=?',[$a->user['id'],now_ms(),trim($b['reason']),$c['id']]);$a->audit($a->user['id'],'reopen_payroll:'.$month);return [200,['ok'=>true]];}
 return null;
}
function roster_schedule(App $a,int $id,string $day): array {$starts=[];if(function_exists('expected_shifts'))foreach(expected_shifts($a,$id,$day) as $shift=>$e){$starts[$shift]=$e['expected_at'];}return ['enabled'=>(bool)$starts,'shifts'=>array_keys($starts),'starts'=>$starts];}
function roster_routes(App $a,string $path,array $b,string $method): ?array {
 if($path!=='/roster'&&!str_starts_with($path,'/roster/'))return null;
 if($path==='/roster'&&$method==='GET'){$start=valid_day($_GET['start']??'');$end=valid_day($_GET['end']??'');$days=(strtotime($end)-strtotime($start))/86400;if($days<0||$days>61)fail('Chỉ xem tối đa 62 ngày mỗi lần.');$staff=$a->user['role']==='employee';$assignments=$a->all('SELECT a.*,u.name,u.role,u.status,u.archived,u.employee_code FROM {{shift_assignments}} a JOIN {{users}} u ON u.id=a.user_id WHERE a.day>=? AND a.day<=?'.($staff?' AND a.user_id=?':'').' ORDER BY a.day,a.shift,u.name',[$start,$end,...($staff?[$a->user['id']]:[])]);$derived=booking_roster($a,$start,$end);$assignments=array_values(array_filter($assignments,fn($r)=>!isset($derived[$r['user_id'].'_'.$r['day'].'_'.$r['shift']])));$assignments=[...$assignments,...array_values($derived)];if(function_exists('avail_roster'))$assignments=[...$assignments,...avail_roster($a,$start,$end,$staff?$a->user['id']:null,$assignments)];$people=$a->all("SELECT id,name,role,status,employee_code,department,job_title FROM {{users}} WHERE archived=0 AND status!='inactive'".($staff?' AND id=?':'').' ORDER BY name',$staff?[$a->user['id']]:[]);return [200,['assignments'=>$assignments,'people'=>$people,'shifts'=>SHIFTS,'legacyImport'=>$staff?null:json_decode($a->scalar("SELECT value FROM {{roster_meta}} WHERE `key`='legacy_import'")?:'null',true)]];}
 $a->requireManager();
 if($path==='/roster/assign'&&$method==='POST'){$day=valid_day($b['day']??'');$shift=$b['shift']??'';if(!in_array($shift,['day_first','day_second'],true))fail('Chỉ phân Ca 1 hoặc Ca 2.');$ids=$b['user_ids']??[$b['user_id']??null];if(!is_array($ids)||!$ids||count($ids)>100)fail('Chọn từ 1 đến 100 nhân viên.');$ids=array_values(array_unique($ids,SORT_REGULAR));foreach($ids as $id){if(!is_int($id))fail('Nhân viên không hợp lệ.');$a->target($id);}$created=[];foreach($ids as $id){if($a->one('SELECT id FROM {{shift_assignments}} WHERE user_id=? AND day=? AND shift=?',[$id,$day,$shift]))continue;$a->run('INSERT INTO {{shift_assignments}}(user_id,day,shift,created_by,created_at,updated_by,updated_at) VALUES(?,?,?,?,?,?,?)',[$id,$day,$shift,$a->user['id'],now_ms(),$a->user['id'],now_ms()]);$row=$a->one('SELECT * FROM {{shift_assignments}} WHERE id=?',[(int)$a->db->lastInsertId()]);roster_audit($a,'assign',null,$row);$created[]=$row;}if(!$created)fail('Nhân viên đã được phân ca này, không tạo trùng.',409);return [201,['assignments'=>$created]];}
 if(preg_match('~^/roster/(\d+)/(move|delete)$~D',$path,$m)&&$method==='POST'){$id=(int)$m[1];$old=$a->one('SELECT * FROM {{shift_assignments}} WHERE id=?',[$id]);if(!$old)fail('Phân ca đã bị xóa. Hãy tải lại lịch.',409);$a->target($old['user_id'],$m[2]==='delete');if(!is_int($b['version']??null)||$b['version']!==$old['version'])fail('Lịch đã được người khác thay đổi. Hãy tải lại trước khi sửa.',409);if($m[2]==='delete'){$a->run('DELETE FROM {{shift_assignments}} WHERE id=?',[$id]);roster_audit($a,'delete',$old,null);}else{$day=valid_day($b['day']??'');$shift=$b['shift']??'';if(!in_array($shift,['day_first','day_second'],true))fail('Ca làm không hợp lệ.');if($a->one('SELECT id FROM {{shift_assignments}} WHERE user_id=? AND day=? AND shift=? AND id!=?',[$old['user_id'],$day,$shift,$id]))fail('Nhân viên đã có trong ca đích.',409);$a->run('UPDATE {{shift_assignments}} SET day=?,shift=?,version=version+1,updated_by=?,updated_at=? WHERE id=?',[$day,$shift,$a->user['id'],now_ms(),$id]);roster_audit($a,'move',$old,$a->one('SELECT * FROM {{shift_assignments}} WHERE id=?',[$id]));}return [200,['ok'=>true]];}
 fail('Không tìm thấy chức năng phân ca.',404);
}
function roster_audit(App $a,string $action,?array $before,?array $after): void {$r=$after??$before;$a->run('INSERT INTO {{roster_audit}}(actor_id,assignment_id,user_id,action,before_json,after_json,time) VALUES(?,?,?,?,?,?,?)',[$a->user['id'],$r['id'],$r['user_id'],$action,$before?json_encode($before,JSON_THROW_ON_ERROR):null,$after?json_encode($after,JSON_THROW_ON_ERROR):null,now_ms()]);}
